-- Add missing RLS UPDATE policy for quiz_attempts
create policy "users update own quizzes"
  on quiz_attempts for update using (auth.uid() = user_id);

-- =============================================================================
-- AUD — Auditing and Attestation (section_id = 1)
-- 30 questions: 8 easy, 14 medium, 8 hard
-- =============================================================================
insert into questions (section_id, topic, stem, choices, correct_index, explanation, difficulty) values

-- Ethics and Independence (3 questions)
(1, 'Ethics and Independence',
 'Which of the following situations would most likely impair an auditor''s independence?',
 '["The auditor''s spouse owns a material direct financial interest in the client", "The auditor performs tax return preparation for the client", "The auditor provides management advisory services to the client", "The auditor''s firm has an office in the same building as the client"]'::jsonb,
 0,
 'A direct financial interest owned by an auditor''s immediate family member (spouse) is considered a financial interest that impairs independence regardless of materiality under AICPA and SEC rules. Tax preparation and advisory services, while requiring safeguards, do not automatically impair independence. Sharing office space has no bearing on independence.',
 'easy'),

(1, 'Ethics and Independence',
 'Under the AICPA Code of Professional Conduct, which of the following services, if provided to an attest client, would most likely impair independence?',
 '["Preparing tax returns based on information provided by the client", "Making management decisions on behalf of the client", "Providing advice on internal control improvements", "Assisting with the implementation of an accounting software system"]'::jsonb,
 1,
 'Making management decisions on behalf of a client is a management participation threat that impairs independence because the auditor is assuming a role that belongs to management. The auditor must not act as a member of client management or make decisions for them. The other services are permissible when appropriate safeguards are in place.',
 'medium'),

(1, 'Ethics and Independence',
 'A CPA firm is evaluating threats to independence for a new audit client. The engagement partner''s brother is the client''s CFO. Under the conceptual framework approach, which threat category does this represent?',
 '["Self-review threat", "Advocacy threat", "Familiarity threat", "Undue influence threat"]'::jsonb,
 2,
 'A close family relationship between the engagement team and client management creates a familiarity threat, where the auditor may become too sympathetic to the client''s interests due to the personal relationship. Self-review involves auditing one''s own work, advocacy involves promoting a client''s position, and undue influence involves the client pressuring the auditor.',
 'medium'),

-- Audit Planning (3 questions)
(1, 'Audit Planning',
 'During audit planning, the auditor establishes materiality for the financial statements as a whole. Which of the following best describes the purpose of this determination?',
 '["To decide whether to accept the engagement", "To determine the scope of audit procedures and evaluate misstatements", "To establish the audit fee", "To assess the client''s going concern status"]'::jsonb,
 1,
 'Materiality is established during planning to determine the nature, timing, and extent of audit procedures and to evaluate whether identified misstatements, individually or in aggregate, are material to the financial statements. It is a key planning tool that drives the entire audit approach, not a factor in engagement acceptance, fee setting, or going concern evaluation.',
 'easy'),

(1, 'Audit Planning',
 'An auditor is planning an audit and has determined that overall materiality for the financial statements is $500,000. The auditor sets performance materiality at $375,000. What is the primary reason for setting performance materiality lower than overall materiality?',
 '["To increase audit fees through additional testing", "To reduce the risk that aggregate uncorrected and undetected misstatements exceed overall materiality", "To ensure all misstatements above $375,000 are corrected", "To satisfy regulatory requirements for public companies"]'::jsonb,
 1,
 'Performance materiality is set below overall materiality to account for the possibility that multiple undetected misstatements could aggregate to exceed overall materiality. By testing at a lower threshold, the auditor builds in a buffer to reduce the risk that the sum of uncorrected and undetected misstatements exceeds the amount considered material for the financial statements as a whole.',
 'medium'),

(1, 'Audit Planning',
 'An auditor is developing the overall audit strategy. Which of the following factors would the auditor least likely consider?',
 '["The entity''s industry and regulatory environment", "The entity''s selection and application of accounting policies", "The expected fee revenue from the engagement", "The results of preliminary engagement activities"]'::jsonb,
 2,
 'The overall audit strategy considers the characteristics of the engagement, reporting objectives, and the nature and timing of resources needed. Fee revenue is a business matter for the firm, not a factor in developing the audit strategy. Industry conditions, accounting policies, and preliminary engagement activities are all directly relevant to planning the audit approach.',
 'easy'),

-- Risk Assessment (3 questions)
(1, 'Risk Assessment',
 'Under AU-C 315, the auditor is required to identify and assess risks of material misstatement. Which two components make up the risk of material misstatement?',
 '["Audit risk and detection risk", "Inherent risk and control risk", "Sampling risk and nonsampling risk", "Business risk and information risk"]'::jsonb,
 1,
 'The risk of material misstatement (RMM) is the product of inherent risk and control risk. Inherent risk is the susceptibility of an assertion to a misstatement before considering internal controls, while control risk is the risk that a misstatement will not be prevented or detected by the entity''s internal controls. Detection risk is the auditor''s component and is managed by adjusting audit procedures.',
 'easy'),

(1, 'Risk Assessment',
 'An auditor identifies a significant risk related to revenue recognition. Which of the following audit responses would be most appropriate?',
 '["Reduce the planned extent of substantive procedures for revenue", "Rely primarily on the client''s internal controls over revenue without further testing", "Obtain more persuasive audit evidence, such as confirming terms with major customers", "Remove revenue from the scope of the audit"]'::jsonb,
 2,
 'When a significant risk is identified, the auditor must obtain more persuasive evidence. This often includes external confirmations, detailed testing, or other procedures that provide higher-quality evidence. Significant risks require heightened attention and cannot be addressed by reducing procedures, relying solely on untested controls, or removing the area from scope.',
 'medium'),

(1, 'Risk Assessment',
 'During risk assessment, the auditor becomes aware that the client recently changed its revenue recognition policy and implemented a new ERP system simultaneously. Which of the following best describes the auditor''s concern?',
 '["The changes are routine and do not affect the audit approach", "The combination creates a higher inherent risk for revenue-related assertions due to process change and system migration", "The auditor should withdraw from the engagement due to increased risk", "The changes only affect control risk, not inherent risk"]'::jsonb,
 1,
 'Simultaneous changes in accounting policy and information systems create elevated inherent risk because new processes may contain errors, staff may not be fully trained, and data migration introduces the possibility of misstatement. These compound changes affect both inherent risk (new policy application) and control risk (new system controls), requiring enhanced audit procedures.',
 'hard'),

-- Internal Controls (3 questions)
(1, 'Internal Controls',
 'Which of the following is a component of internal control as defined by the COSO framework?',
 '["Substantive testing", "Analytical procedures", "Control environment", "Engagement quality review"]'::jsonb,
 2,
 'The COSO internal control framework identifies five components: control environment, risk assessment, control activities, information and communication, and monitoring activities. Substantive testing and analytical procedures are audit procedures, not internal control components. Engagement quality review is a firm-level quality control measure.',
 'easy'),

(1, 'Internal Controls',
 'An auditor plans to rely on the operating effectiveness of a client''s internal controls. Which of the following procedures must the auditor perform?',
 '["Inquiry of management only", "Observation of the control environment", "Tests of controls, including reperformance or inspection of evidence of control operation", "Review of the client''s organizational chart"]'::jsonb,
 2,
 'When the auditor plans to rely on controls, AU-C 330 requires testing the operating effectiveness of those controls through tests of controls. This typically involves reperformance, inspection of documents showing the control operated, or a combination of procedures. Inquiry alone is insufficient, and observation of the general environment or reviewing an org chart does not constitute a test of controls.',
 'medium'),

(1, 'Internal Controls',
 'During the evaluation of a client''s information processing controls, the auditor discovers that the same employee who initiates purchase orders also approves the related vendor invoices and records the transactions. Which internal control principle is being violated?',
 '["The principle of adequate documentation", "The principle of independent checks", "The principle of segregation of duties", "The principle of physical controls over assets"]'::jsonb,
 2,
 'Segregation of duties requires that authorization, custody, and recording functions be performed by different individuals to prevent and detect errors or fraud. When one person initiates transactions, approves them, and records them, there is no independent check on that person''s activities, creating an opportunity for misappropriation or misstatement.',
 'easy'),

-- Audit Evidence (2 questions)
(1, 'Audit Evidence',
 'Which of the following forms of audit evidence is generally considered the most reliable?',
 '["Oral representations from management", "Documents generated internally by the client", "External confirmations received directly from third parties", "Analytical procedures performed by the auditor"]'::jsonb,
 2,
 'External confirmations received directly from independent third parties are generally considered the most reliable form of audit evidence because they originate outside the entity and are transmitted directly to the auditor, reducing the risk of manipulation. Internal documents can be altered, management representations are self-serving, and analytical procedures provide indirect evidence.',
 'easy'),

(1, 'Audit Evidence',
 'An auditor sends positive confirmation requests to 100 of the client''s accounts receivable customers. Thirty confirmations are returned with no exceptions, and 70 are not returned despite a second request. What is the most appropriate next step?',
 '["Accept the 30 returned confirmations as sufficient evidence for the entire receivable balance", "Issue a qualified audit opinion due to scope limitation", "Perform alternative procedures on the nonresponses, such as examining subsequent cash receipts or shipping documents", "Assume the nonresponding customers agree with the recorded balances"]'::jsonb,
 2,
 'When positive confirmations are not returned, the auditor cannot assume agreement with the recorded balance (that is the assumption under negative confirmations). The auditor must perform alternative procedures on the nonresponses, such as inspecting subsequent cash receipts, examining shipping documents, or reviewing sales contracts to obtain sufficient evidence about those balances.',
 'medium'),

-- Audit Sampling (2 questions)
(1, 'Audit Sampling',
 'In statistical sampling for tests of controls, which of the following would lead the auditor to increase the sample size?',
 '["An increase in the tolerable rate of deviation", "A decrease in the expected population deviation rate", "A decrease in the acceptable risk of overreliance", "An increase in the population size from 5,000 to 50,000 items"]'::jsonb,
 2,
 'A decrease in the acceptable risk of overreliance means the auditor wants greater confidence that the sample results reflect the true population. To achieve this higher confidence, a larger sample is needed. Increasing the tolerable rate or decreasing the expected deviation rate would reduce the required sample size. Population size has minimal effect on sample size for large populations.',
 'hard'),

(1, 'Audit Sampling',
 'An auditor uses monetary unit sampling (MUS) to test accounts receivable. What is the primary advantage of this method?',
 '["It requires no statistical knowledge to apply", "It automatically stratifies the population by dollar amount, giving larger items a higher probability of selection", "It eliminates the need for an understanding of the client''s business", "It guarantees detection of all misstatements above the tolerable misstatement"]'::jsonb,
 1,
 'Monetary unit sampling selects individual dollars as the sampling unit, which means larger account balances contain more sampling units and have a proportionally higher chance of being selected. This built-in stratification focuses the audit on high-dollar items without requiring a separate stratification step, making it efficient for testing overstatement of asset balances.',
 'medium'),

-- Substantive Procedures (2 questions)
(1, 'Substantive Procedures',
 'An auditor is performing substantive analytical procedures on a client''s payroll expense. Which of the following would develop the most precise expectation?',
 '["Comparing total payroll expense to the prior year", "Multiplying the average number of employees by the average salary rate per pay period by the number of pay periods", "Reviewing payroll expense as a percentage of total revenue", "Inquiring of the HR director about payroll changes"]'::jsonb,
 1,
 'Building an expectation using disaggregated data (number of employees x average rate x number of periods) produces a more precise estimate than top-level comparisons or ratio analysis. The more independent and specific the data used to form the expectation, the more effective the analytical procedure is at detecting misstatements.',
 'medium'),

(1, 'Substantive Procedures',
 'Which of the following substantive procedures would be most effective in detecting unrecorded liabilities?',
 '["Confirming accounts payable balances with vendors", "Examining cash disbursements made after year-end", "Vouching recorded payables to supporting documentation", "Recalculating accrued liabilities using management''s assumptions"]'::jsonb,
 1,
 'Examining cash disbursements after the balance sheet date is the most effective procedure for detecting unrecorded liabilities because payments made after year-end may relate to obligations that existed at year-end but were not recorded. Confirming existing balances only verifies what is already recorded, and vouching tests recorded items rather than searching for omissions.',
 'medium'),

-- Audit Reports (3 questions)
(1, 'Audit Reports',
 'In an auditor''s unmodified opinion report on a nonissuer, which of the following statements is included?',
 '["The financial statements are guaranteed to be free of misstatement", "The audit was conducted in accordance with generally accepted auditing standards", "The auditor assumes responsibility for the entity''s internal controls", "The financial statements are the responsibility of the auditor"]'::jsonb,
 1,
 'The standard unmodified audit report states that the audit was conducted in accordance with auditing standards generally accepted in the United States (GAAS). The report clarifies that management is responsible for the financial statements and that the auditor''s responsibility is to express an opinion. Audits provide reasonable, not absolute, assurance.',
 'easy'),

(1, 'Audit Reports',
 'An auditor determines that a client''s financial statements contain a material misstatement related to the incorrect classification of a long-term debt as a current liability. If management refuses to correct the misstatement, what type of opinion should the auditor issue?',
 '["Unmodified opinion", "Qualified opinion due to material misstatement", "Adverse opinion", "Disclaimer of opinion"]'::jsonb,
 1,
 'A material misstatement that is not pervasive to the financial statements results in a qualified opinion. Misclassification of debt between current and long-term is material but typically does not pervade the entire financial statements. An adverse opinion would be appropriate if the misstatement were both material and pervasive. A disclaimer is for scope limitations, not misstatements.',
 'medium'),

(1, 'Audit Reports',
 'An auditor is issuing a report on financial statements that are prepared in accordance with a special purpose framework (cash basis). Which of the following is required in the auditor''s report?',
 '["An adverse opinion because the statements do not conform to GAAP", "A paragraph that restricts the use of the report to management only", "An emphasis-of-matter paragraph that describes the special purpose framework and refers to the note in the financial statements", "A disclaimer of opinion due to the departure from GAAP"]'::jsonb,
 2,
 'When reporting on special purpose framework financial statements, the auditor includes an emphasis-of-matter paragraph describing the applicable financial reporting framework and referring to the note that describes it. The auditor can issue an unmodified opinion on these statements because they are evaluated against the special purpose framework, not GAAP.',
 'hard'),

-- Review/Compilation Engagements (3 questions)
(1, 'Review/Compilation Engagements',
 'In a review engagement, the practitioner provides which level of assurance?',
 '["Reasonable assurance", "Absolute assurance", "Limited assurance", "No assurance"]'::jsonb,
 2,
 'A review engagement provides limited (also called negative) assurance, where the practitioner states that nothing came to their attention that causes them to believe the financial statements are not in accordance with the applicable framework. This contrasts with reasonable (positive) assurance provided in an audit and no assurance in a compilation.',
 'easy'),

(1, 'Review/Compilation Engagements',
 'During a compilation engagement, the accountant becomes aware that the financial statements contain a material departure from GAAP. Management is informed and declines to revise the statements. What action should the accountant take?',
 '["Withdraw from the engagement immediately", "Issue the compilation report with a paragraph disclosing the departure from GAAP", "Issue an adverse opinion on the financial statements", "Perform additional procedures to determine the effect of the departure"]'::jsonb,
 1,
 'In a compilation engagement, if management declines to correct a known GAAP departure, the accountant should disclose the departure in a separate paragraph of the compilation report. The accountant is not required to withdraw unless the departure is intended to mislead. Compilations do not result in opinions, so an adverse opinion is not applicable.',
 'medium'),

(1, 'Review/Compilation Engagements',
 'Which of the following procedures is required in a review engagement but NOT in a compilation engagement?',
 '["Reading the financial statements for obvious errors", "Inquiry of management about accounting principles", "Obtaining a management representation letter", "All of the above"]'::jsonb,
 3,
 'A review engagement requires inquiry and analytical procedures, including inquiries about accounting principles, reading the financial statements, and obtaining a management representation letter. A compilation requires only understanding the client''s business and reading the statements for obvious errors. The representation letter, formal inquiries, and analytical procedures distinguish a review from a compilation.',
 'hard'),

-- Attestation Engagements (2 questions)
(1, 'Attestation Engagements',
 'Under SSAE standards, an examination engagement on subject matter results in what type of conclusion?',
 '["A disclaimer of opinion", "A negative assurance conclusion", "A positive opinion on whether the subject matter is presented in accordance with the criteria", "A recommendation for improvement"]'::jsonb,
 2,
 'An examination engagement under SSAE standards results in a positive opinion, similar to an audit opinion, stating whether the subject matter is in accordance with (or based on) the established criteria. This provides the highest level of assurance among attestation engagement types. Negative assurance is associated with review-level attestation engagements.',
 'medium'),

(1, 'Attestation Engagements',
 'A practitioner is engaged to perform an agreed-upon procedures engagement on a client''s compliance with certain loan covenants. Which of the following is a characteristic of this type of engagement?',
 '["The practitioner expresses an opinion on overall compliance", "The report is restricted to specified parties who agreed to the procedures", "The practitioner provides negative assurance on the subject matter", "The practitioner must be independent of the engaging party"]'::jsonb,
 1,
 'In an agreed-upon procedures engagement, the practitioner reports findings from performing specific procedures that were agreed upon by the specified parties. The report is restricted to those parties because only they understand the context and sufficiency of the procedures. The practitioner does not express an opinion or provide assurance, but reports factual findings.',
 'medium'),

-- Quality Management (2 questions)
(1, 'Quality Management',
 'Under SQMS No. 1 (Statement on Quality Management Standards), which of the following is a required component of a firm''s system of quality management?',
 '["Marketing and business development standards", "The firm''s risk assessment process for identifying quality risks", "Client profitability analysis procedures", "Staff compensation benchmarking"]'::jsonb,
 1,
 'SQMS No. 1 requires firms to establish a risk-based approach to quality management, including a risk assessment process that identifies quality risks and designs responses to address them. The eight components include governance and leadership, ethical requirements, acceptance and continuance, engagement performance, resources, information and communication, and monitoring and remediation.',
 'medium'),

(1, 'Quality Management',
 'An engagement quality reviewer is assigned to an audit of an issuer (public company). At what point must the engagement quality review be completed?',
 '["Within 30 days after the report release date", "Before the engagement report is released", "Before the start of the subsequent year''s audit", "After the audit committee approves the financial statements"]'::jsonb,
 1,
 'The engagement quality review must be completed before the auditor''s report is released. The reviewer evaluates significant judgments and conclusions to provide an additional safeguard for audit quality. Releasing the report before the review is complete would defeat the purpose of this quality control mechanism.',
 'hard'),

(1, 'Audit Evidence',
 'An auditor is testing the completeness assertion for accounts payable. Which of the following procedures would be most effective?',
 '["Confirming balances with vendors who have large outstanding balances", "Tracing a sample of receiving reports issued before year-end to the accounts payable listing", "Vouching recorded payable balances to vendor invoices", "Reviewing the accounts payable aging schedule for past-due amounts"]'::jsonb,
 1,
 'Testing completeness requires searching for items that should be recorded but may not be. Tracing from receiving reports (evidence that goods were received) to the payable listing determines whether the corresponding liability was recorded. Confirming existing balances and vouching recorded items test existence and accuracy, not completeness. The aging schedule only analyzes balances already recorded.',
 'hard'),

(1, 'Substantive Procedures',
 'An auditor suspects that fictitious sales have been recorded near year-end. Which combination of procedures would be most effective in detecting this fraud?',
 '["Confirming year-end receivable balances and tracing sales to shipping documents", "Recalculating the allowance for doubtful accounts and reviewing the aging schedule", "Performing analytical procedures on gross margin and comparing to prior years", "Inspecting credit memos issued after year-end and reviewing sales returns"]'::jsonb,
 0,
 'Fictitious sales create receivables with no underlying transaction. Confirming receivables directly with customers tests whether the customer acknowledges the debt, and tracing sales to shipping documents verifies that goods were actually shipped. Together, these procedures address both the receivable and the underlying transaction. Analytical procedures and credit memo reviews may provide indirect evidence but are less targeted for detecting fictitious revenue.',
 'hard'),

-- =============================================================================
-- FAR — Financial Accounting and Reporting (section_id = 2)
-- 30 questions: 8 easy, 14 medium, 8 hard
-- =============================================================================
(2, 'Financial Statements',
 'Which of the following financial statements reports an entity''s financial position at a specific point in time?',
 '["Income statement", "Statement of cash flows", "Balance sheet", "Statement of comprehensive income"]'::jsonb,
 2,
 'The balance sheet (statement of financial position) reports assets, liabilities, and equity at a specific point in time, providing a snapshot of the entity''s financial position. The income statement, statement of cash flows, and statement of comprehensive income all report activity over a period of time.',
 'easy'),

(2, 'Financial Statements',
 'Under ASC 205-40, management must evaluate whether there is substantial doubt about an entity''s ability to continue as a going concern. What is the required evaluation period?',
 '["Six months from the balance sheet date", "One year from the date the financial statements are issued or available to be issued", "Two years from the balance sheet date", "The period covered by the financial statements"]'::jsonb,
 1,
 'ASC 205-40 requires management to evaluate whether conditions or events raise substantial doubt about the entity''s ability to continue as a going concern within one year after the date the financial statements are issued (or available to be issued). This forward-looking assessment uses the issuance date, not the balance sheet date, as the starting point.',
 'medium'),

(2, 'Financial Statements',
 'A company discovers in March 2026 that a warehouse destroyed by a fire in January 2026 was uninsured. The financial statements for the year ended December 31, 2025 have not yet been issued. How should this event be treated?',
 '["Adjust the December 31, 2025 financial statements to reflect the loss", "Disclose the event in the notes to the December 31, 2025 financial statements without adjusting", "Ignore the event because it occurred after year-end", "Record the loss in the 2026 financial statements only"]'::jsonb,
 1,
 'The fire occurred in January 2026 and represents a nonrecognized subsequent event (Type II) because it arose from conditions that did not exist at the balance sheet date. Such events require disclosure in the notes but no adjustment to the financial statements. Recognition would only be appropriate if the conditions giving rise to the loss existed at December 31, 2025.',
 'hard'),

(2, 'Revenue Recognition',
 'Under ASC 606, what is the first step in the five-step revenue recognition model?',
 '["Determine the transaction price", "Identify the performance obligations in the contract", "Identify the contract with a customer", "Allocate the transaction price to the performance obligations"]'::jsonb,
 2,
 'The five-step model under ASC 606 begins with identifying the contract with a customer. The steps in order are: (1) identify the contract, (2) identify performance obligations, (3) determine the transaction price, (4) allocate the transaction price, and (5) recognize revenue when (or as) each performance obligation is satisfied.',
 'easy'),

(2, 'Revenue Recognition',
 'A software company sells a bundled package that includes a software license and two years of technical support for $120,000. The standalone selling price of the license is $90,000, and the standalone price of two years of support is $30,000. How much revenue should be allocated to the software license?',
 '["$120,000", "$90,000", "$60,000", "$80,000"]'::jsonb,
 1,
 'Under ASC 606, the transaction price is allocated to each performance obligation based on its relative standalone selling price. Since the total standalone selling prices ($90,000 + $30,000 = $120,000) equal the transaction price ($120,000), there is no discount to allocate. The software license receives $90,000 and the support receives $30,000.',
 'medium'),

(2, 'Revenue Recognition',
 'A construction company enters into a contract to build a bridge for $10 million. The company determines that the performance obligation is satisfied over time because the customer controls the asset as it is created. At year-end, the company has incurred $3 million of the estimated $8 million total costs. What amount of revenue should be recognized?',
 '["$3,000,000", "$3,750,000", "$10,000,000", "$0"]'::jsonb,
 1,
 'Using the cost-to-cost method (input method) under ASC 606, the percentage of completion is $3M / $8M = 37.5%. Revenue recognized is 37.5% x $10M = $3,750,000. This method measures progress toward completion based on costs incurred relative to total expected costs and is commonly used for long-term construction contracts.',
 'medium'),

(2, 'Inventory',
 'Under U.S. GAAP, which of the following inventory costing methods is NOT permitted?',
 '["First-in, first-out (FIFO)", "Last-in, first-out (LIFO)", "Weighted-average cost", "Next-in, first-out (NIFO)"]'::jsonb,
 3,
 'NIFO (next-in, first-out) uses replacement cost rather than historical cost and is not permitted under U.S. GAAP. FIFO, LIFO, and weighted-average are all acceptable inventory cost flow assumptions. GAAP requires inventory to be valued at historical cost (subject to the lower of cost or net realizable value test).',
 'easy'),

(2, 'Inventory',
 'A company uses the LIFO method and reports inventory of $500,000 at year-end. The LIFO reserve is $80,000. What would inventory be under FIFO?',
 '["$420,000", "$500,000", "$580,000", "$480,000"]'::jsonb,
 2,
 'The LIFO reserve represents the difference between inventory valued at FIFO and inventory valued at LIFO. To convert from LIFO to FIFO: FIFO inventory = LIFO inventory + LIFO reserve = $500,000 + $80,000 = $580,000. In periods of rising prices, LIFO reports lower inventory values, and the reserve captures this difference.',
 'medium'),

(2, 'Fixed Assets',
 'A company purchases equipment for $200,000 with an estimated useful life of 10 years and a residual value of $20,000. Using the straight-line method, what is the annual depreciation expense?',
 '["$20,000", "$18,000", "$22,000", "$16,000"]'::jsonb,
 1,
 'Straight-line depreciation is calculated as (Cost - Residual Value) / Useful Life = ($200,000 - $20,000) / 10 = $18,000 per year. This method allocates the depreciable base evenly over the asset''s useful life, resulting in the same expense each period.',
 'easy'),

(2, 'Fixed Assets',
 'A company capitalizes interest during the construction of a qualifying asset. Which of the following costs is included in the capitalized interest calculation?',
 '["Interest on all outstanding debt regardless of purpose", "Only interest on debt specifically incurred for the construction project", "Interest on specific construction debt plus a weighted-average rate applied to other borrowings to the extent of additional asset expenditures", "Only imputed interest on equity funds used for construction"]'::jsonb,
 2,
 'Under ASC 835-20, capitalizable interest includes: (1) interest on debt specifically incurred for the qualifying asset, and (2) interest on other borrowings at a weighted-average rate, applied to cumulative asset expenditures that exceed specific borrowings. This two-tiered approach captures the interest cost that could have been avoided if expenditures had not been made.',
 'hard'),

(2, 'Intangible Assets',
 'Under U.S. GAAP, which of the following intangible assets is NOT amortized?',
 '["A patent with a remaining legal life of 15 years", "A franchise agreement with a 20-year term", "Goodwill recognized in a business combination", "A customer list with an estimated useful life of 5 years"]'::jsonb,
 2,
 'Goodwill is an indefinite-lived intangible asset that is not amortized under U.S. GAAP (for public companies). Instead, it is tested for impairment at least annually. Patents, franchise agreements, and customer lists have finite useful lives and are amortized over their estimated useful life or legal life, whichever is shorter.',
 'easy'),

(2, 'Intangible Assets',
 'A company acquires a trademark in a business combination valued at $1 million with an indefinite useful life. Two years later, the carrying amount is still $1 million and the fair value is determined to be $850,000. What is the impairment loss?',
 '["$0", "$150,000", "$850,000", "$1,000,000"]'::jsonb,
 1,
 'For indefinite-lived intangible assets other than goodwill, impairment exists when the carrying amount exceeds the fair value. The impairment loss is $1,000,000 - $850,000 = $150,000. The asset is written down to its fair value of $850,000. Unlike finite-lived assets, indefinite-lived intangibles do not have an undiscounted cash flow recoverability test.',
 'medium'),

(2, 'Leases',
 'Under ASC 842, a lessee classifies a lease as a finance lease if any one of several criteria is met. Which of the following is one of those criteria?',
 '["The lease term is less than 12 months", "The present value of lease payments equals at least 75% of the asset''s fair value", "The lease does not transfer ownership", "The lessor retains all risks and rewards of ownership"]'::jsonb,
 1,
 'Under ASC 842, a lease is classified as a finance lease if any of the following criteria are met: (1) ownership transfers, (2) the lease contains a purchase option reasonably certain to be exercised, (3) the lease term is for the major part of the asset''s economic life, (4) the present value of lease payments is substantially all of the asset''s fair value, or (5) the asset is specialized. The 75% and 90% thresholds from ASC 840 remain common bright-line benchmarks.',
 'medium'),

(2, 'Leases',
 'A company enters into a 5-year lease for office space with annual lease payments of $50,000 paid at the end of each year. The company''s incremental borrowing rate is 6%. The present value of an ordinary annuity of $1 at 6% for 5 years is 4.21236. What is the initial right-of-use asset under ASC 842?',
 '["$250,000", "$210,618", "$200,000", "$236,000"]'::jsonb,
 1,
 'Under ASC 842, the right-of-use asset is initially measured at the amount of the lease liability, adjusted for any lease payments made at or before commencement, lease incentives received, and initial direct costs. The lease liability is the present value of future lease payments: $50,000 x 4.21236 = $210,618. Assuming no prepayments, incentives, or direct costs, the ROU asset equals the lease liability.',
 'medium'),

(2, 'Bonds and Debt',
 'A company issues $1,000,000 face value bonds at 98. What is the journal entry for the issuance?',
 '["Debit Cash $1,000,000; Credit Bonds Payable $1,000,000", "Debit Cash $980,000; Debit Discount on Bonds Payable $20,000; Credit Bonds Payable $1,000,000", "Debit Cash $980,000; Credit Bonds Payable $980,000", "Debit Cash $1,020,000; Credit Bonds Payable $1,000,000; Credit Premium on Bonds Payable $20,000"]'::jsonb,
 1,
 'When bonds are issued at a discount (below face value), cash received is less than the face value. The discount ($1,000,000 - $980,000 = $20,000) is a contra-liability account that is amortized over the life of the bond. The entry debits Cash for $980,000, debits Discount on Bonds Payable for $20,000, and credits Bonds Payable for the full face value of $1,000,000.',
 'medium'),

(2, 'Bonds and Debt',
 'A company issues a $500,000, 5-year, 8% bond when the market rate is 10%. The bond pays interest semiannually. Using the effective interest method, which of the following is true about the interest expense recognized in the first period?',
 '["Interest expense equals the cash interest payment of $20,000", "Interest expense is less than the cash interest payment because the bond was issued at a discount", "Interest expense is greater than the cash interest payment because the carrying amount is multiplied by the market rate", "Interest expense equals $25,000, which is the face value times the market rate"]'::jsonb,
 2,
 'Under the effective interest method, interest expense is calculated as the carrying amount of the bond multiplied by the market rate per period. Since the bond was issued at a discount (stated rate < market rate), the carrying amount is below face value but interest expense (carrying amount x 5%) will exceed the cash payment (face x 4% = $20,000). The discount amortization is the difference between expense and cash paid.',
 'hard'),

(2, 'Equity',
 'When a company declares a small stock dividend (less than 20-25% of outstanding shares), at what value are the additional shares recorded?',
 '["Par value", "Book value per share", "Fair market value on the declaration date", "The original issue price of the shares"]'::jsonb,
 2,
 'For small stock dividends (generally less than 20-25% of outstanding shares), the shares distributed are recorded at fair market value on the declaration date. Retained earnings is debited for the fair value, common stock is credited for the par value of new shares, and additional paid-in capital is credited for the excess. This treatment reflects the presumption that a small distribution has minimal effect on market price.',
 'medium'),

(2, 'Equity',
 'A company repurchases 10,000 shares of its own $1 par value common stock at $25 per share using the cost method. What is the journal entry?',
 '["Debit Treasury Stock $250,000; Credit Cash $250,000", "Debit Treasury Stock $10,000; Debit APIC $240,000; Credit Cash $250,000", "Debit Common Stock $10,000; Credit Cash $10,000", "Debit Retained Earnings $250,000; Credit Cash $250,000"]'::jsonb,
 0,
 'Under the cost method of accounting for treasury stock, the repurchase is recorded at the total cost paid. Treasury stock is debited for $250,000 (10,000 shares x $25) and Cash is credited for $250,000. The par value and original issue price are not relevant under the cost method until the shares are subsequently retired or reissued.',
 'easy'),

(2, 'Income Taxes',
 'A company has a temporary difference that will result in taxable amounts in future years. This gives rise to which of the following?',
 '["A deferred tax asset", "A deferred tax liability", "A current tax receivable", "A tax credit carryforward"]'::jsonb,
 1,
 'A temporary difference that will result in taxable amounts in future years creates a deferred tax liability because the company will owe additional taxes when the difference reverses. Common examples include depreciation differences where tax depreciation exceeds book depreciation, creating a future taxable amount when book depreciation exceeds tax depreciation in later years.',
 'easy'),

(2, 'Income Taxes',
 'A company has a deferred tax asset of $300,000 related to a net operating loss carryforward. Management determines it is more likely than not that only $200,000 of the deferred tax asset will be realized. What is the required valuation allowance?',
 '["$0", "$100,000", "$200,000", "$300,000"]'::jsonb,
 1,
 'Under ASC 740, a valuation allowance is established when it is more likely than not (greater than 50% likelihood) that some portion of the deferred tax asset will not be realized. Since management expects only $200,000 to be realized, a valuation allowance of $100,000 ($300,000 - $200,000) is needed to reduce the net deferred tax asset to its expected realizable amount.',
 'medium'),

(2, 'Governmental Accounting',
 'In governmental accounting, which fund type uses the modified accrual basis of accounting?',
 '["Enterprise funds", "Internal service funds", "General fund", "Pension trust funds"]'::jsonb,
 2,
 'Governmental funds, including the general fund, special revenue funds, capital projects funds, debt service funds, and permanent funds, use the modified accrual basis of accounting. Under this basis, revenues are recognized when they are measurable and available, and expenditures are recognized when the related liability is incurred. Proprietary and fiduciary funds use full accrual accounting.',
 'medium'),

(2, 'Governmental Accounting',
 'A city receives a $2 million state grant restricted for road construction. In which fund should this grant be reported?',
 '["General fund", "Capital projects fund", "Enterprise fund", "Permanent fund"]'::jsonb,
 1,
 'Restricted grants for capital projects are typically reported in a capital projects fund, which accounts for financial resources restricted, committed, or assigned for the acquisition or construction of major capital assets (other than those financed by proprietary or fiduciary funds). The general fund is for unrestricted resources, and enterprise funds are for business-type activities.',
 'medium'),

(2, 'Not-for-Profit Accounting',
 'Under ASC 958, a not-for-profit organization classifies net assets into which two categories?',
 '["Restricted and unrestricted", "Net assets with donor restrictions and net assets without donor restrictions", "Temporarily restricted and permanently restricted", "Operating and nonoperating"]'::jsonb,
 1,
 'Following the ASU 2016-14 update to ASC 958, not-for-profit organizations classify net assets into two categories: net assets with donor restrictions and net assets without donor restrictions. This replaced the previous three-category system of unrestricted, temporarily restricted, and permanently restricted. The change simplified reporting while still conveying information about restrictions.',
 'medium'),

(2, 'Not-for-Profit Accounting',
 'A donor contributes $500,000 to a not-for-profit hospital and specifies that the principal must be maintained in perpetuity, with income available for general operations. How should this contribution be classified?',
 '["Net assets without donor restrictions", "Net assets with donor restrictions", "Revenue in the operating section", "A liability until the terms are met"]'::jsonb,
 1,
 'Contributions with donor-imposed restrictions are classified as net assets with donor restrictions. Since the donor requires the principal to be maintained in perpetuity, this is a perpetual restriction. When the investment income is earned and has no further restrictions, it is reported as net assets without donor restrictions (or with time/purpose restrictions if specified by the donor).',
 'hard'),

(2, 'Consolidations',
 'A parent company owns 80% of a subsidiary. In the consolidated financial statements, how should the noncontrolling interest be presented?',
 '["As a liability on the consolidated balance sheet", "As a separate component of stockholders'' equity on the consolidated balance sheet", "As a deduction from the parent''s retained earnings", "It is not presented; only the parent''s 80% share is reported"]'::jsonb,
 1,
 'Under ASC 810, the noncontrolling interest (NCI) is presented as a separate component of equity in the consolidated balance sheet, not as a liability or mezzanine item. Consolidated statements include 100% of the subsidiary''s assets, liabilities, revenues, and expenses, with the NCI representing the portion of equity not attributable to the parent.',
 'medium'),

(2, 'Consolidations',
 'During the preparation of consolidated financial statements, which of the following intercompany transactions must be eliminated?',
 '["Only intercompany sales of inventory", "Only intercompany loans and interest", "All intercompany transactions, including sales, loans, dividends, and unrealized profits", "Only transactions that exceed materiality thresholds"]'::jsonb,
 2,
 'All intercompany transactions must be eliminated in consolidation to present the consolidated entity as if it were a single economic entity. This includes intercompany sales and cost of goods sold, intercompany receivables and payables, intercompany loans and interest, intercompany dividends, and any unrealized profits on intercompany transfers of assets.',
 'hard'),

(2, 'Leases',
 'Under ASC 842, which of the following is recognized on a lessee''s balance sheet for an operating lease?',
 '["Only a lease liability with no corresponding asset", "A right-of-use asset and a lease liability", "Neither an asset nor a liability", "Only a right-of-use asset with no corresponding liability"]'::jsonb,
 1,
 'ASC 842 requires lessees to recognize both a right-of-use asset and a lease liability on the balance sheet for virtually all leases, including operating leases (with an optional exemption for short-term leases of 12 months or less). This was a major change from ASC 840, which only required balance sheet recognition for capital (finance) leases.',
 'easy'),

(2, 'Revenue Recognition',
 'A company sells gift cards redeemable for merchandise. Under ASC 606, when should the company recognize revenue for gift card sales?',
 '["When the gift card is sold", "When the gift card is redeemed by the customer, or when the likelihood of redemption becomes remote (breakage)", "At the end of the fiscal year in which the gift card was sold", "Ratably over the expected redemption period beginning at the date of sale"]'::jsonb,
 1,
 'Gift card proceeds represent a contract liability (deferred revenue) until the performance obligation is satisfied. Revenue is recognized when the customer redeems the gift card (satisfying the performance obligation) or when the entity determines the customer is unlikely to exercise remaining rights (breakage). Under ASC 606, breakage revenue is recognized proportionally as other gift cards are redeemed, if the entity expects to be entitled to the breakage amount.',
 'hard'),

(2, 'Income Taxes',
 'A company has a temporary difference arising from a $100,000 warranty accrual that is not deductible for tax purposes until paid. The enacted tax rate is 21%. What deferred tax effect does this create?',
 '["A deferred tax liability of $21,000", "A deferred tax asset of $21,000", "No deferred tax effect", "A current tax receivable of $21,000"]'::jsonb,
 1,
 'The warranty accrual creates a future deductible amount because the expense is recognized on the books now but will be deducted for tax purposes when paid in the future. This gives rise to a deferred tax asset of $100,000 x 21% = $21,000, reflecting the future tax benefit when the temporary difference reverses. Deferred tax assets arise from future deductible amounts, while deferred tax liabilities arise from future taxable amounts.',
 'hard'),

(2, 'Governmental Accounting',
 'Which of the following is reported as a component unit in a government''s comprehensive annual financial report?',
 '["A separate legal entity that is fiscally dependent on the primary government", "A federal agency that provides grants to the government", "A private business operating within the government''s jurisdiction", "A neighboring government with shared boundaries"]'::jsonb,
 0,
 'A component unit is a legally separate organization for which the primary government is financially accountable or whose relationship with the primary government is such that exclusion would cause misleading financial statements. Fiscal dependence (the entity cannot adopt its own budget, set rates, or issue debt without the primary government''s approval) is one of the key criteria for financial accountability under GASB standards.',
 'hard'),

-- =============================================================================
-- REG — Taxation and Regulation (section_id = 3)
-- 30 questions: 8 easy, 14 medium, 8 hard
-- =============================================================================
(3, 'Circular 230',
 'Under Treasury Circular 230, which of the following individuals is authorized to practice before the IRS?',
 '["Any individual with a college degree in accounting", "A registered tax return preparer with unlimited representation rights", "An enrolled agent who has passed the Special Enrollment Examination", "A bookkeeper who has prepared tax returns for more than 5 years"]'::jsonb,
 2,
 'Enrolled agents are authorized to practice before the IRS with unlimited representation rights after passing the Special Enrollment Examination (SEE) or having sufficient IRS experience. CPAs and attorneys also have unlimited representation rights. Registered tax return preparers have limited rights, and a college degree or bookkeeping experience alone does not grant practice privileges.',
 'easy'),

(3, 'Circular 230',
 'Under Circular 230, a practitioner must exercise due diligence in preparing tax returns. Which of the following would most likely constitute a violation of this requirement?',
 '["Relying on information provided by the client without independent verification when the information appears reasonable", "Signing a tax return that contains a position with a reasonable basis", "Failing to inquire about missing information that the practitioner knows is relevant to the return", "Using a tax software program to calculate the tax liability"]'::jsonb,
 2,
 'Due diligence requires the practitioner to make reasonable inquiries if information appears incomplete, inconsistent, or incorrect. Failing to follow up on known missing information that is relevant to the return is a violation. Relying on client information that appears reasonable is generally acceptable, and using software or taking positions with reasonable basis are permissible practices.',
 'medium'),

(3, 'Business Law: Contracts',
 'Which of the following is required for a valid contract under common law?',
 '["A written document signed by both parties", "Offer, acceptance, consideration, capacity, and legality", "Notarization by a licensed notary public", "Approval by an attorney"]'::jsonb,
 1,
 'A valid contract requires five elements: (1) a valid offer, (2) acceptance of that offer, (3) consideration (something of value exchanged), (4) legal capacity of the parties, and (5) a legal purpose. Not all contracts must be written (only those falling under the Statute of Frauds), and neither notarization nor attorney approval is generally required.',
 'easy'),

(3, 'Business Law: Contracts',
 'Under the Statute of Frauds, which of the following contracts must be in writing to be enforceable?',
 '["A contract for the sale of a used car for $400", "A contract for services to be completed within two weeks", "A contract for the sale of land", "An oral agreement to paint a house for $600"]'::jsonb,
 2,
 'The Statute of Frauds requires certain contracts to be in writing, including contracts for the sale of an interest in land, contracts that cannot be performed within one year, contracts for the sale of goods over $500 (under the UCC), suretyship agreements, and contracts in consideration of marriage. A contract for the sale of land always falls within the Statute of Frauds.',
 'medium'),

(3, 'Business Law: Contracts',
 'A makes an offer to B on Monday. On Wednesday, A sends a letter revoking the offer. B receives the revocation on Friday. On Thursday, before receiving the revocation, B mails a letter of acceptance. Under the mailbox rule, when was the contract formed?',
 '["Wednesday, when A sent the revocation", "Thursday, when B mailed the acceptance", "Friday, when B received the revocation", "No contract was formed because A revoked before B received the offer"]'::jsonb,
 1,
 'Under the mailbox rule, acceptance is effective when dispatched (mailed), while revocation is effective only when received. B mailed acceptance on Thursday, before receiving the revocation on Friday. Therefore, the acceptance was effective on Thursday, creating a binding contract before the revocation could take effect.',
 'hard'),

(3, 'Agency and Regulation',
 'In an agency relationship, which of the following best describes apparent authority?',
 '["Authority explicitly granted in a written agreement", "Authority that a third party reasonably believes the agent possesses based on the principal''s conduct", "Authority that the agent assumes without the principal''s knowledge", "Authority granted by a court order"]'::jsonb,
 1,
 'Apparent authority arises when a principal''s words or conduct would lead a reasonable third party to believe the agent has authority to act, even if no actual authority was granted. The principal is bound by the agent''s actions within the scope of apparent authority because the third party reasonably relied on the appearance of authority created by the principal.',
 'medium'),

(3, 'Agency and Regulation',
 'A principal hires an agent to sell goods. The agent, acting within the scope of employment, negligently injures a customer during a delivery. Under respondeat superior, who is liable?',
 '["Only the agent, because the agent committed the negligent act", "Only the principal, because the agent was acting within the scope of employment", "Both the principal and the agent are jointly and severally liable", "Neither party, because the injury was unintentional"]'::jsonb,
 2,
 'Under the doctrine of respondeat superior, both the principal (employer) and agent (employee) are liable when the agent commits a tort within the scope of employment. The principal is vicariously liable for the agent''s negligence, and the agent remains personally liable for their own tortious conduct. The injured party can recover from either or both parties.',
 'medium'),

(3, 'Business Structures',
 'Which of the following business structures provides limited liability protection to all of its owners?',
 '["General partnership", "Sole proprietorship", "Limited liability company (LLC)", "General partnership with a DBA registration"]'::jsonb,
 2,
 'An LLC provides limited liability protection to all of its members, meaning their personal assets are generally shielded from business debts and liabilities. General partners in a general partnership have unlimited personal liability, as do sole proprietors. A DBA registration does not change the liability structure of a general partnership.',
 'easy'),

(3, 'Business Structures',
 'Which of the following is a key difference between an S corporation and a C corporation?',
 '["S corporations cannot have shareholders", "C corporations are pass-through entities while S corporations are not", "S corporation income is generally taxed only at the shareholder level, avoiding double taxation", "C corporations are limited to 100 shareholders"]'::jsonb,
 2,
 'The primary distinction is tax treatment: S corporation income, losses, deductions, and credits pass through to shareholders'' individual returns, avoiding the double taxation that C corporations face (corporate tax plus shareholder tax on dividends). C corporations are taxed at the entity level. It is S corporations, not C corporations, that are limited to 100 shareholders.',
 'easy'),

(3, 'Property Transactions: Basis',
 'A taxpayer receives property as a gift with a donor''s adjusted basis of $30,000 and a fair market value of $50,000 at the date of the gift. No gift tax was paid. What is the recipient''s basis for computing gain on a subsequent sale?',
 '["$0", "$30,000", "$50,000", "$40,000"]'::jsonb,
 1,
 'For gifted property where the FMV at the date of the gift exceeds the donor''s adjusted basis, the recipient''s basis for computing gain is the donor''s adjusted basis (carryover basis), which is $30,000. If gift tax had been paid, a portion of the gift tax attributable to the appreciation would be added to the basis. The FMV is only relevant for determining basis if the property is later sold at a loss.',
 'medium'),

(3, 'Property Transactions: Basis',
 'A taxpayer inherits stock from a decedent who died on June 15, 2025. The decedent''s adjusted basis in the stock was $40,000, and the fair market value on the date of death was $95,000. What is the heir''s basis in the stock?',
 '["$40,000", "$95,000", "$67,500", "$55,000"]'::jsonb,
 1,
 'Under IRC Section 1014, the basis of property acquired from a decedent is generally stepped up (or down) to the fair market value on the date of death. The heir''s basis becomes $95,000, regardless of the decedent''s original cost basis of $40,000. This stepped-up basis eliminates the unrealized gain that accrued during the decedent''s lifetime.',
 'easy'),

(3, 'Property Transactions: Gains/Losses',
 'A taxpayer sells Section 1231 property at a gain. Assuming no Section 1231 losses in the current or prior five years, how is this gain treated?',
 '["Ordinary income", "Long-term capital gain", "Short-term capital gain", "Not taxable"]'::jsonb,
 1,
 'Net Section 1231 gains are treated as long-term capital gains, which receive preferential tax rates. However, the Section 1231 lookback rule requires that net 1231 gains be recharacterized as ordinary income to the extent of unrecaptured net 1231 losses from the prior five years. With no prior losses, the full gain receives long-term capital gain treatment.',
 'medium'),

(3, 'Property Transactions: Gains/Losses',
 'A taxpayer sells equipment used in a business for $80,000. The equipment was purchased for $100,000 and has accumulated depreciation of $35,000. What is the amount and character of the gain or loss?',
 '["$15,000 ordinary gain under Section 1245 depreciation recapture", "$15,000 Section 1231 gain", "$20,000 ordinary loss", "$15,000 long-term capital gain"]'::jsonb,
 0,
 'The adjusted basis is $100,000 - $35,000 = $65,000. The gain is $80,000 - $65,000 = $15,000. Under Section 1245, gain on the sale of personal property (equipment) is recaptured as ordinary income to the extent of accumulated depreciation. Since the $15,000 gain is less than the $35,000 of accumulated depreciation, the entire $15,000 gain is ordinary income under Section 1245.',
 'hard'),

(3, 'Like-Kind Exchanges',
 'Under Section 1031, which of the following types of property qualifies for like-kind exchange treatment?',
 '["Inventory held for sale to customers", "Stocks and bonds", "Real property held for investment or used in a trade or business", "Personal-use vacation homes"]'::jsonb,
 2,
 'After the Tax Cuts and Jobs Act of 2017, Section 1031 like-kind exchanges are limited to real property held for productive use in a trade or business or for investment. Inventory, stocks, bonds, partnership interests, and personal-use property do not qualify. Both the relinquished and replacement properties must be real property.',
 'easy'),

(3, 'Like-Kind Exchanges',
 'A taxpayer exchanges an investment property (adjusted basis $200,000, FMV $350,000) for a like-kind property (FMV $300,000) plus $50,000 cash. What is the recognized gain?',
 '["$0", "$50,000", "$150,000", "$100,000"]'::jsonb,
 1,
 'In a like-kind exchange, gain is recognized only to the extent of boot received. The realized gain is $350,000 (FMV given) - $200,000 (basis) = $150,000. The boot received is $50,000 cash. The recognized gain is the lesser of the realized gain ($150,000) or the boot received ($50,000), so $50,000 is recognized. The remaining $100,000 gain is deferred.',
 'medium'),

(3, 'Individual Taxation: Income',
 'Which of the following is excluded from gross income under the Internal Revenue Code?',
 '["Wages and salaries", "Gambling winnings", "Gifts and inheritances received", "Alimony received under a pre-2019 divorce agreement"]'::jsonb,
 2,
 'Under IRC Section 102, the value of property acquired by gift or inheritance is excluded from gross income. Wages, gambling winnings, and alimony received under pre-2019 agreements are all includable in gross income. Note that for divorce agreements executed after December 31, 2018, alimony is no longer included in the recipient''s income due to TCJA changes.',
 'easy'),

(3, 'Individual Taxation: Income',
 'A taxpayer receives a signing bonus of $10,000 from a new employer on December 28, 2025. The taxpayer deposits the check on January 3, 2026. In which year must the bonus be included in gross income?',
 '["2025, under the constructive receipt doctrine", "2026, when the check was deposited", "Split between both years", "Whichever year the taxpayer elects"]'::jsonb,
 0,
 'Under the constructive receipt doctrine, income is recognized when it is made available to the taxpayer without substantial limitation, regardless of when it is actually deposited or collected. The taxpayer had the right to the funds on December 28, 2025, when the check was received, so the bonus must be included in 2025 gross income.',
 'medium'),

(3, 'Individual Taxation: Income',
 'A cash-basis taxpayer receives $5,000 in rental income in December 2025 for January 2026 rent. How should this be reported?',
 '["As income in 2026 when earned", "As income in 2025 when received", "As deferred revenue in 2025", "Split $2,500 in each year"]'::jsonb,
 1,
 'A cash-basis taxpayer reports income when it is received, regardless of when it is earned. The $5,000 rental payment received in December 2025 is included in the taxpayer''s 2025 gross income, even though it relates to a January 2026 rental period. Deferral of prepaid income is generally not available to cash-basis taxpayers for rental income.',
 'medium'),

(3, 'Individual Taxation: Credits/AMT',
 'Which of the following tax benefits is a credit rather than a deduction?',
 '["Mortgage interest on a primary residence", "State and local taxes paid", "Child tax credit", "Charitable contributions"]'::jsonb,
 2,
 'The child tax credit directly reduces the amount of tax owed (dollar-for-dollar), whereas mortgage interest, state and local taxes, and charitable contributions are deductions that reduce taxable income. Credits are generally more valuable than deductions of the same amount because they reduce tax liability directly rather than just reducing the income subject to tax.',
 'easy'),

(3, 'Individual Taxation: Credits/AMT',
 'For 2025, a married couple filing jointly has a regular tax liability of $45,000 and tentative minimum tax of $52,000 under the alternative minimum tax (AMT) calculation. What is their AMT?',
 '["$52,000", "$45,000", "$7,000", "$97,000"]'::jsonb,
 2,
 'The AMT is calculated as the excess of the tentative minimum tax over the regular tax. AMT = $52,000 - $45,000 = $7,000. The total tax liability is the regular tax plus the AMT: $45,000 + $7,000 = $52,000 (which equals the tentative minimum tax). The AMT ensures taxpayers pay at least the tentative minimum tax amount.',
 'medium'),

(3, 'Individual Taxation: Credits/AMT',
 'A taxpayer pays $8,000 in qualified higher education expenses for a dependent child attending college full-time. The taxpayer''s modified AGI is within the phase-out range for the American Opportunity Tax Credit. Before the phase-out, what is the maximum credit amount?',
 '["$8,000", "$4,000", "$2,500", "$2,000"]'::jsonb,
 2,
 'The American Opportunity Tax Credit is calculated as 100% of the first $2,000 of qualified expenses plus 25% of the next $2,000, for a maximum credit of $2,500 per eligible student. The $8,000 in expenses exceeds the cap, so the maximum credit before any phase-out reduction is $2,500. Up to 40% of the credit ($1,000) is refundable.',
 'medium'),

(3, 'C Corporations',
 'A C corporation has taxable income of $500,000 for the current year. Under the Tax Cuts and Jobs Act (TCJA), what is the federal corporate tax rate applied to this income?',
 '["15%", "21%", "25%", "35%"]'::jsonb,
 1,
 'The TCJA established a flat 21% federal corporate tax rate for C corporations, replacing the prior graduated rate structure that ranged from 15% to 35%. This flat rate applies to all taxable income regardless of the amount, resulting in a federal tax of $105,000 on $500,000 of taxable income.',
 'easy'),

(3, 'C Corporations',
 'A C corporation receives $100,000 in dividends from a domestic corporation in which it owns a 25% interest. What is the dividends received deduction (DRD)?',
 '["$50,000 (50%)", "$65,000 (65%)", "$100,000 (100%)", "$0"]'::jsonb,
 1,
 'The dividends received deduction depends on the ownership percentage. For ownership of 20% or more but less than 80%, the DRD is 65% of the dividends received. Since the corporation owns 25%, the DRD is $100,000 x 65% = $65,000. Ownership below 20% receives a 50% DRD, and ownership of 80% or more receives a 100% DRD (subject to taxable income limitations).',
 'hard'),

(3, 'C Corporations',
 'A C corporation accumulates earnings beyond the reasonable needs of the business. What penalty tax may be imposed?',
 '["Alternative minimum tax", "Personal holding company tax", "Accumulated earnings tax", "Built-in gains tax"]'::jsonb,
 2,
 'The accumulated earnings tax is a penalty tax imposed on C corporations that accumulate earnings and profits beyond the reasonable needs of the business to avoid distributing dividends to shareholders. The tax is imposed at 20% on accumulated taxable income. The first $250,000 ($150,000 for personal service corporations) of accumulated earnings is generally considered a safe harbor.',
 'medium'),

(3, 'S Corporations',
 'Which of the following would cause an S corporation to lose its S election?',
 '["Having fewer than 50 shareholders", "Issuing a second class of stock with different distribution rights", "Distributing profits to shareholders", "Filing a consolidated return"]'::jsonb,
 1,
 'An S corporation is limited to one class of stock. If the corporation issues a second class of stock with different distribution or liquidation rights, it violates the S corporation eligibility requirements and the S election is automatically terminated. Other disqualifying events include exceeding 100 shareholders, having an ineligible shareholder (such as a C corporation), or having a nonresident alien shareholder.',
 'medium'),

(3, 'S Corporations',
 'An S corporation reports ordinary business income of $200,000 for the year. Shareholder A owns 40% of the stock and had a stock basis of $50,000 at the beginning of the year. The corporation distributes $100,000 to Shareholder A during the year. What is Shareholder A''s stock basis at year-end?',
 '["$30,000", "$50,000", "$80,000", "$130,000"]'::jsonb,
 0,
 'Shareholder A''s basis is adjusted as follows: Beginning basis $50,000 + allocable share of income (40% x $200,000 = $80,000) = $130,000 - distribution of $100,000 = $30,000. Income increases basis before distributions reduce it, ensuring the distribution is tax-free to the extent of basis. The ordering of these adjustments is critical under IRC Section 1368.',
 'hard'),

(3, 'S Corporations',
 'An S corporation shareholder wants to deduct their share of an S corporation loss. The loss deduction is limited to which of the following?',
 '["The shareholder''s stock basis only", "The shareholder''s stock basis plus debt basis from loans the shareholder made directly to the corporation", "The shareholder''s stock basis plus the corporation''s total debt", "There is no limitation on loss deductions"]'::jsonb,
 1,
 'An S corporation shareholder can deduct losses only to the extent of their stock basis plus their direct loan basis (loans made by the shareholder to the corporation). Unlike partnerships, guarantees of corporate debt do not create basis for S corporation shareholders. Losses exceeding the combined stock and debt basis are suspended and carried forward indefinitely.',
 'hard'),

(3, 'Partnerships',
 'When a partner contributes property to a partnership in exchange for a partnership interest, what is the partnership''s basis in the contributed property?',
 '["Fair market value at the date of contribution", "The contributing partner''s adjusted basis (carryover basis)", "Zero", "One-half of the fair market value"]'::jsonb,
 1,
 'Under IRC Section 723, the partnership''s basis in contributed property is the contributing partner''s adjusted basis (carryover basis). This is consistent with the general nonrecognition treatment of partnership formations under Section 721, where no gain or loss is recognized on contribution. The partner''s outside basis is determined under Section 722.',
 'medium'),

(3, 'Partnerships',
 'Partner X has an outside basis in a partnership of $60,000. The partnership distributes $45,000 cash and property with an inside basis of $25,000 (FMV $30,000) in a nonliquidating distribution. What is Partner X''s basis in the distributed property?',
 '["$25,000", "$15,000", "$30,000", "$0"]'::jsonb,
 1,
 'In a nonliquidating distribution, cash reduces basis first. After the $45,000 cash distribution, Partner X''s remaining basis is $60,000 - $45,000 = $15,000. The distributed property takes a carryover basis of $25,000, but it cannot exceed the partner''s remaining outside basis of $15,000. Therefore, the property''s basis to Partner X is $15,000. The partner''s outside basis is reduced to $0.',
 'hard'),

(3, 'Partnerships',
 'A partnership has three equal partners. The partnership reports $300,000 of ordinary business income, $15,000 of long-term capital gains, and $9,000 of charitable contributions. What is the amount of ordinary business income reported on each partner''s Schedule K-1?',
 '["$100,000", "$92,000", "$102,000", "$98,000"]'::jsonb,
 0,
 'Separately stated items (long-term capital gains and charitable contributions) must be reported separately on each partner''s K-1 because they may be subject to different treatment on each partner''s individual return. Only the $300,000 ordinary business income is reported as the partnership''s nonseparately stated income. Each partner''s share is $300,000 / 3 = $100,000. The capital gains and charitable contributions flow through separately.',
 'medium');
